// ── Boot ───────────────────────────────────────────────────
async function boot() {
	// WHICH ROOT THE FILE TOOLS ARE READING, said once, so the derived "in cloud
	// storage and not on this device" list is computed against the same filesystem
	// `file_list` answers from. Registered rather than reached for: cloud.js is
	// loaded before this file and must not go looking upward for a handle this
	// closure owns.
	if (window.DaimondCloud && DaimondCloud.useRoot) DaimondCloud.useRoot(sharedFolderHandle);
	initTheme();
	initSkin();
	// After the skin: the view inherits from it on a first run.
	initView();
	// A face's metrics are not final until it has actually loaded -- the
	// composer is fit against the fallback face's line-height until then, on
	// whatever skin is current at that moment. One refit once every `@font-face`
	// in use has resolved (QA round 2, M1); a browser with no Font Loading API
	// just keeps the fit `initSkin`/`initTheme` already gave it.
	if (document.fonts && document.fonts.ready) {
		document.fonts.ready.then(function () {
			try { fitComposer(); } catch (e) { /* the composer is not bound yet */ }
		}).catch(function () { /* nothing to refit against */ });
	}
	// Only the provider API key is masked as text-with-bullets now. It is
	// somebody else's bearer credential against somebody else's billing, so
	// there is no reason for it to reach a personal keychain. The passphrase
	// fields are REAL password inputs (see index.html): the passphrase is
	// generated, so there is nothing weak or reused to save, and a manager
	// holding it is what stops it being retyped on a phone all day.
	installSecretMask(document.getElementById('cfg-api-key'), '');
	// The push token is masked the same way and for the same reason: it is a
	// credential against the user's own repositories, and a real password field
	// is what invites a manager to file it away.
	installSecretMask(document.getElementById('cfg-push-token'), '');
	// Every secret field in the served page wears the eye (secret.js), so a
	// long one typed on a phone can be checked. The search key is masked and
	// given its own when its row is wired (SearchRow.mount).
	['id-pass', 'id-pass2', 'cfg-api-key', 'cfg-push-token'].forEach(function (fid) {
		secretEye(document.getElementById(fid));
	});
	// The create screen's own controls: regenerate, copy, the written-it-down
	// acknowledgement, and the way out to a typed passphrase.
	var regenBtn = document.getElementById('id-regen');
	if (regenBtn) regenBtn.addEventListener('click', function () { regenerate(); });
	var copyBtn = document.getElementById('id-gencopy');
	if (copyBtn) copyBtn.addEventListener('click', async function () {
		var v = getSecret(document.getElementById('id-pass'));
		try {
			await navigator.clipboard.writeText(v);
			copyBtn.textContent = t('toast.copied');
			setTimeout(function () { copyBtn.textContent = t('common.copy'); }, 1500);
		} catch (e) {
			// No clipboard permission (or an insecure context): the words are
			// on screen anyway, which is the path that matters.
			copyBtn.textContent = t('changepass.select_above');
			setTimeout(function () { copyBtn.textContent = t('common.copy'); }, 2000);
		}
	});
	var wroteBox = document.getElementById('id-wrote');
	if (wroteBox) wroteBox.addEventListener('change', syncPrimaryEnabled);
	var chooseBtn = document.getElementById('id-choose');
	if (chooseBtn) chooseBtn.addEventListener('click', function () {
		if (idGenMode) {
			// Generated → typed. Clear the generated words rather than leave
			// them sitting in a box the user is now meant to type their own into.
			setGenMode(false);
			var inp = document.getElementById('id-pass');
			if (inp) { setSecret(inp, ''); try { inp.focus(); } catch (e) {} }
			setSecret(document.getElementById('id-pass2'), '');
		} else {
			// Typed → generated. A FRESH passphrase, never whatever was typed:
			// the readout must show words this device picked, and the tick below
			// it says they were written down. Showing a half-typed secret there
			// would invite writing down something the user was still editing.
			setSecret(document.getElementById('id-pass2'), '');
			if (regenerate()) setGenMode(true);
		}
	});
	// A browser may fill its own suggested password into the field. The
	// readout follows the field so the words shown are always the words used.
	var passInp = document.getElementById('id-pass');
	if (passInp) passInp.addEventListener('input', function () {
		if (idGenMode) syncGenReadout();
	});
	// The form is a real form so the browser sees a real submission, which is
	// what makes it offer to save the credential. Enter and the button both
	// arrive here.
	var idForm = document.getElementById('id-form');
	if (idForm) idForm.addEventListener('submit', function (ev) {
		ev.preventDefault();
		idPrimary();
	});
	DaimondPanels.init();
	watchAgentsPanel();      // after init: the closers it listens through are bound there
	DaimondAdmin.init();
	initPauseUi();
	initCompose();           // its buttons answer from the first moment, draft or none
	if (window.DaimondMail) {
		DaimondMail.init({
			writeBytes:   Files.writeBytes,
			// Mail reads message BYTES, so it must not go through
			// `run_tool('file_read')` — that is the model-facing rendering, which
			// numbers every line and wraps an untrusted path in an envelope.
			// `parseHeaders` saw `1\tFrom: …` and matched nothing, so every message
			// in the panel read "(unknown) / (no subject)". Same fault as the Doc
			// panel's, in a second place. See `readRaw` at :11835.
			// `readBytes`, not `Wasm.read_file` direct: it is the same call with the
			// withdrawn-grant alarm on it, and Mail reads the user's folder like
			// anything else here.
			readText:     readBytes,
			// A message as bytes, for `wasm.mail_view`, which reads its charset itself.
			readBytes:    readRawBytes,
			openFile:     Files.open,
			// The workspace tree. Mail calls this at every moment a draft file can
			// appear or vanish -- saving one, discarding one, sending one -- so the
			// tree shows the folder as it now is. It used to sweep the Pending panel
			// too, back when a tile could be waiting on that draft; no kind of tile
			// waits on a file any more.
			refreshFiles: function () { Files.refresh(); },
			// `{ text, outcome }`, not the bare text: mail read that text for the word
			// `Error` to decide whether a listing was a listing, and a refusal opens
			// `Refused` -- so a refused mailbox read as a mailbox with nothing in it.
			runTool:      function (name, args) {
				return tools().run_tool_outcome(name, JSON.stringify(args || {}));
			},
			showMessage:  showMessage,
			showCompose:  showCompose,
			mailDialog:   mailDialog,
			// The mailbox settings dialog, which is phase C's tile dialog wearing a
			// different body. Asked for by name in `mail.js` since phase G part one,
			// which shipped a stand-in of the same furniture rather than a gear that
			// opened nothing.
			bodyDialog:   openBodyDialog,
			// The caller names its own button. Removing a mailbox is destructive and
			// wants a red Remove; fetching a mailbox down is not, and a red button
			// on it would say the wrong thing about what is about to happen.
			confirm:      function (msg, detail, opts) {
				opts = opts || {};
				return confirmDialog(detail || '', opts.ok || 'OK',
					{ title: msg, danger: !!opts.danger });
			},
		});
	}
	if (window.DaimondModels) {
		// The store is loaded (and the old single-provider config carried into it) before
		// anything asks what model to run on.
		// The resolver reads each Diamond's and chat's own picks through these (D-20261018-09 U1b).
		DaimondModels.bindPicks({ diamond: diamondPicks, chat: chatPicks, summarising: summarisingPick,
			list: everyoneTargets, clear: clearPick, set: setPick, settle: settlePicks });
		DaimondModels.init({
			onChange: function () {
				syncCfgFromModels();
				nudgeSync();	// a provider or key change outside a turn pushes on its own
				DaimondAdmin.status();
				// The panel is a view of the store, so it follows the store. Without this it only
				// redrew when the thing that changed the store happened to remember to ask -- so
				// unlocking with the Models panel open left every provider still reading "sealed".
				DaimondModels.render();
				// So is the composer's Effort step: a fetched model list is what names its levels.
				try { renderEffortStep(); } catch (e) { /* drawn again on the next view */ }
			},
			// The one thing a credits row can offer that a key row cannot: the way to fix it.
			// The models panel does not own the credits form, so it asks for it rather than
			// growing a second copy.
			onTopUp: function () { openCredits('Top up to keep using these models.'); },
		});
		syncCfgFromModels();
	}
	if (window.DaimondSearch) {
		// The same shape as the models store beside it, for the same reason: the
		// row is a view of the store, so it follows the store rather than waiting
		// for whoever changed it to remember to ask.
		DaimondSearch.init({
			onChange: function () { SearchRow.render(); },
		});
		SearchRow.render();
	}
	if (window.DaimondTools) {
		DaimondTools.init({
			// The registry the agent is actually handed, not a list of it kept in JavaScript.
			builtins: function () { return JSON.parse(builtin_tools()); },
			// The count is what the rail row says, so the panel tells the rail when it changes
			// rather than the rail asking on a timer.
			onCount:  function () { DaimondAdmin.status(); },
		});
	}
	// The Typst driver installs `window.DaimondTypst`, which is the ONE object the Rust
	// `typst_compile` tool looks for. It is a module, so nothing installs it until something
	// imports it -- and the tool cannot import anything. Without this the tool was in the
	// belt and could never work: a model asked for a PDF correctly reported that it could
	// not make one. The heavy compiler wasm is still built lazily, on the first compile;
	// this only evaluates the ~4 KB module that registers the driver.
	import('../typst.js' /* page-split: rebased */).catch(function () { /* no Typst on this build; the tool says so */ });
	if (window.DaimondWeb) DaimondWeb.init({
		// A consequential web action — a purchase, a send — is put to the USER,
		// never confirmed by the model. Resolves true only on a real yes.
		confirm: function (reason) {
			return confirmDialog(reason, t('confirm.yes_do_it'), {
				title: t('confirm.irreversible'),
				danger: true,
				// Re-check of 2026-09-23, R6: raised by the running turn while the
				// person may be typing elsewhere, so it takes the same guard as the
				// held delete -- focus on Cancel, and no stray key for a second.
				guard: true,
			});
		},
		// Read a file from the active workspace (OPFS or a real folder), so the
		// Web panel can open a page the agent has just written there. Returns
		// the text, or throws if there is no such file.
		readFile: function (path) {
			return readBytes(path);
		},
	});
	// The machine hand is the browser build's route to a process, and the `run`
	// tool reaches it through `window.DaimondHand` exactly as the web tools reach
	// `window.DaimondWeb`. Nothing used to wire it: the relay was in the page and
	// never spoken to, so the handshake that reports the granted folder was never
	// sent, and without that folder there is no fence to express and every command
	// was refused. This is the wiring — and only the wiring. The link itself opens
	// LAZILY, on the first thing that needs a hand, because opening it is what puts
	// the approval window on the user's screen and a question that arrives merely
	// because the app started is one a person learns to dismiss.
	if (window.DaimondHand) DaimondHand.init({
		onStart: function (id, pid) { runLive('[running, process ' + pid + ']\n'); },
		onChunk: function (id, stream, data) { runLive(data); },
		onEnd:   function (id, exit) { runLive('\n[exit code: ' + exit + ']\n'); },
		// The deletion meter is holding a command that has removed the turn's allowance
		// of files that existed before it. Asked in every rung, bypass included, and
		// stopped when nobody answers: the hand gives up waiting after two minutes, so the
		// dialog answers "stop" a little before that on its own.
		//
		// UNBIDDEN, as the held delete is (re-check of 2026-09-23, R6): the running command
		// raises it while the person may be typing elsewhere, and a Space that landed on
		// "Let it go on" would let the command go on removing files. It came in from the
		// hand's own branch after R6's guard had reached every other such question.
		onHeld:  function (id, h) {
			return confirmDialog(t('hand.held_body', { n: h.counted, mark: h.mark }),
				t('hand.held_allow'), {
					title: t('hand.held_title'),
					cancelLabel: t('hand.held_stop'),
					danger: true,
					deadlineMs: 110000,
					onDeadline: function () { return false; },
					ask: 'hand-held',
					guard: true,
				}).then(function (allow) {
					if (allow) return true;
					// Stopped: put back what it took. The hand refuses every removal from
					// the moment it is told to stop, so nothing races the restore.
					DaimondHand.restore(h.since_ms).then(function (r) {
						runLive('\n[' + t('hand.held_back', { n: r.restored }) + ']\n');
					}, function (e) { runLive('\n' + (e && e.message || e) + '\n'); });
					return false;
				});
		},
		// The hand's hello named this computer: fold it into this device's own
		// derived name (see `applyHandHostname`). Fires only once the link is
		// actually open -- nothing here opens it early.
		onHost:  function (host) { applyHandHostname(host); },
		// This computer's hand is older than the deletion meter, so the engine has made
		// every folder read-only to a command and to a file tool (`command_fence` in
		// src/tools.rs). A Pending notice, not a dialog raised over whatever the
		// person is doing -- see `noteHandStale`.
		onMeterless: function (host, version) { noteHandStale(host, version); },
		// What the relay has to say about the hand itself — that it stopped,
		// that it was never installed — rather than about the command. It is
		// written for the model, and a person watching the panel is owed it too.
		note:    function (msg) { runLive('\n' + msg + '\n'); },
		// The folder the user opened, so the relay can settle whether it is the
		// folder the hand was granted (`hand/REVIEW.md` §1.14). A handle and never
		// a path: the File System Access API gives the page no path at all, which
		// is the whole reason the two ends compare a token in a file instead.
		// Null on the browser sandbox, and that is an ANSWER — there is no folder
		// for a command to run against — not a missing one.
		folder:  function () { return Files.folder(); },
	});
	Files.init();
	Workers.render();
	// A promise other modules can await before touching the wasm module, so a panel
	// remembered from a previous session (graph, tools, mail, ...) that draws itself on
	// `mshow` below -- BEFORE `init()` -- does not construct against an undefined `wasm`
	// binding. Published on `DaimondCore`, which already exists by this point, rather than
	// a fresh global, so there is one place readers look. Rejects if `init()` throws, so a
	// waiter does not hang forever on a boot that failed.
	var readyResolve, readyReject;
	window.DaimondCore.ready = new Promise(function (res, rej) { readyResolve = res; readyReject = rej; });
	mshow(document.body.dataset.mpanel || 'ai');
	try {
		await init();               // instantiate the wasm module
		// FIRST, before anything can panic. A wasm panic with no hook is the
		// most opaque failure this app can produce: a bare "Script error." with
		// no file or line, a Promise that never settles, and a poisoned module.
		// An iPhone looped on exactly that for four sessions.
		try { install_panic_hook(); } catch (e) { /* an older bundle has none */ }
		// Last visit's host speeds back into the engine before its first request routes
		// by them (D-20261020-10).
		try { if (window.DaimondHostSpeed) DaimondHostSpeed.attach(Wasm); } catch (e) { /* no figures is a fresh start */ }
		// And the footprint, from the moment there is one to read.
		try { watchHeap(); } catch (e) { /* an older bundle cannot report it */ }
		// The engine id the switch matches a native runner on (R5a). Not awaited.
		learnEngineId().catch(function () { /* none known: no native runner offered */ });
		window.__DAIMOND_READY = true;
		// The module is now safe to construct against. Resolve before anything else in
		// this block, so a panel waiting on it (graph, tools, ...) unblocks as early as
		// possible rather than behind the rest of boot.
		readyResolve();
		try { window.DaimondSeal.markReady(); } catch (e) { /* no seal bridge */ }
		try { document.dispatchEvent(new CustomEvent('daimond:wasm-ready')); } catch (e) {}
		// Point OPFS at the current account's subdirectory BEFORE any file tool runs, so this
		// account's workspace and Daimond's own state are isolated from every other account at
		// this browser. Empty for the primary account (the root, unchanged).
		try { set_account_ns(window.DaimondAccounts ? DaimondAccounts.opfsNs() : ''); }
		catch (e) { /* single-account build */ }
		// The permission ladder. Pushed into the wasm BEFORE any agent runs: the
		// engine's copy is the one that decides anything, and a page drawing
		// "Bypass" over an engine still running guarded would be worse than either
		// being wrong on its own. `apply` is here rather than in handmode.js
		// because the wasm is a module and that file is a classic script.
		if (window.DaimondHandMode) DaimondHandMode.init({
			apply:   applyPermissionMode,
			confirm: confirmDialog,
			notice:  function (m) { toast(m, true); },
			// THIS chat's network, not a chat of the surface's choosing. The
			// permission popover has no idea which conversation is on screen and
			// must not learn: the one it would answer for and the one the user is
			// looking at are the same only by luck. An engine that has not been
			// built yet answers '' and the section is not drawn.
			// THE CONVERSATION ON SCREEN, which is `current` on every face. A
			// Diamond's chat face is an ordinary chat record running through
			// `ensureApp` like any other; `diamondApp` builds a SEPARATE client for
			// the daimon's own steering turns, and that one is shared by every
			// Diamond on the same model ("two Diamonds on the same model are the
			// same client"). Reading it here was tried and reverted: it is not the
			// conversation the chip sits above, and on a Diamond nobody had steered
			// it does not exist at all, so the section simply vanished.
			//
			// WHAT THIS THEREFORE DOES NOT SHOW: a steering turn's own network
			// state. Those turns can read and can run commands, on a client with
			// its own taint and its own answer, and no control anywhere shows it.
			//
			// `current.app` and NOT `ensureApp(current)`: building an engine merely
			// because somebody opened a menu would mint a chat's model, key and
			// generation before they had said anything. A chat with no engine yet
			// has read nothing, so there is nothing to show and nothing to grant.
			netGet: function () {
				return (pg.current && pg.current.app && pg.current.app.net_state)
					? pg.current.app.net_state() : '';
			},
			// EVERY chat that has an engine, not only the one on screen. The
			// standing answer is one answer for all of them, and a chat left open
			// in another tab of the rail would otherwise go on refusing until it
			// was reloaded -- which is the lifetime problem this replaces.
			netApplyAll: function (v) {
				var ans = v === 'allow' ? 'allow' : v === 'refuse' ? 'refuse' : 'ask';
				pg.chats.forEach(function (c) {
					if (c && c.app && c.app.set_net_answer) {
						try { c.app.set_net_answer(ans); } catch (e) { /* a dead engine */ }
					}
				});
			},
		});
		// Warm the write-ahead journal (it self-inits, but opening it now surfaces any storage
		// problem before the first turn rather than during it).
		if (window.DaimondJournal) { try { DaimondJournal.init(); } catch (e) { /* no IDB */ } }
		// The built-in tools live in the wasm registry, so nothing can count them until
		// the module exists. Ask again now that it does, or the rail would report the
		// tools bought and none of the tools built in.
		if (window.DaimondTools) DaimondTools.reload();
		// Reconnect a previously opened real folder (silent if still
		// granted, else a one-click reconnect offer).  Best-effort.
		try { await Files.tryReconnect(); } catch (e) { /* stay on OPFS */ }
	} catch (e) {
		// No-op once `readyResolve` has already settled it; a waiter on a boot that
		// throws before the module is usable must not hang forever.
		try { readyReject(e); } catch (e2) {}
		try { runnerReadyReject(e); } catch (e2) {}
		try { window.DaimondSeal.markFailed(e); } catch (e2) {}
		// A LinkError here is never an ordinary runtime failure. It means the wasm
		// and the JS glue beside it came from DIFFERENT BUILDS -- the module asks for
		// an import the glue does not define -- and that is what a deploy landing
		// mid-session leaves behind: build A's glue already executing, build B's wasm
		// fetched a moment later. Nothing in this page can recover from it, and
		// taking both files again always can, so it repairs itself once rather than
		// showing a user a message about symbol hashes. `repair` holds the loop
		// guard; if it refuses, the message says what is actually wrong.
		var pairBroken = !!(e && (e.name === 'LinkError' || (typeof WebAssembly !== 'undefined'
			&& WebAssembly.LinkError && e instanceof WebAssembly.LinkError)));
		if (pairBroken && window.DaimondUpdater && DaimondUpdater.repair
			&& DaimondUpdater.repair('the engine and its glue are from different builds')) {
			return;                     // reloading; say nothing, it would only flash
		}
		appEl.classList.add('wasm-failed');
		appendError(pairBroken
			? 'The engine and this page came from different builds, and reloading did '
				+ 'not clear it. Your work is safe on this device -- nothing here can '
				+ 'reach it until the two match. Close this tab completely and open it '
				+ 'again; do NOT clear website data, which is where your diamonds live.'
			: 'Failed to load the browser engine: ' + String(e));
		window.__DAIMOND_READY = false;
		return;
	}
	pg.chats = await loadChatsHeld();  // restore persisted chats (survive reload) -- SUMMARIES (seq 213)
	pg.chatsUp = true;
	rebuildDispatchedIndex();   // seed the dispatched-placeholder cache from the summaries
	runnerReadyResolve();       // the engine and the chats are up: errands may be worked now
	// Load the transcripts of the few chats that hold a dispatched placeholder, so the
	// peer subsystem finds them resident (seq 213, Stage 1). Not awaited: the rail is
	// built from summaries above and does not wait on a transcript read.
	ensureDispatchedResident();
	// NOTHING IS SEEDED FROM THIS LIST. A counter used to be, and `loadChats`
	// omits every chat in the trash — which is how a new chat came back with an
	// id the trash still owned. See `newChatId`.
	updateUserRow();

	// Identity gate. A returning user unlocks FIRST: nothing of theirs is
	// drawn until they are in. Rendering the app and then laying a modal
	// over it — the old order — left every chat, name and figure legible
	// behind the lock screen.
	//
	// existsSettled(), NOT exists(): on a cold iOS/WebKit tab the stored keypair
	// can read empty for a tick or two before the storage area loads, and a bare
	// `exists()` there answers "no identity" for an identity sitting on disk —
	// which fell through to "Create passphrase" and minted a fresh salt that
	// orphaned every sealed provider key (the SEV-1). The settled read re-checks
	// across a few ticks and only concludes "no keys" once they have had their
	// chance to appear. It is awaited, so this branch waits for the answer.
	var haveIdentity = identityAvailable() ? await DaimondIdentity.existsSettled() : false;
	// A tab that kept its unlocked session across the reload (Settings › Devices,
	// "Stay unlocked") comes back in through here, not through the lock screen:
	// `restore()` has already opened the wrapping key and fired `daimond:unlock`
	// itself, so the only thing left to do is run the same completion every other
	// unlock path runs -- unseal the provider keys, connect the gateway, draw the
	// app -- rather than showing a passphrase prompt for a tab that never left.
	if (haveIdentity) {
		var back = await DaimondIdentity.restoring();
		if (back && back.ok) {
			await completeUnlock();
			window.__DAIMOND_READY = true;
			return;
		}
	}
	if (haveIdentity) {
		pg.locked = true;
		document.body.classList.add('locked');
		sessionNameEl.textContent = '';
		chatInputBar.style.display = 'none';
		try { DaimondTrail.note('lock screen', 'boot found a stored identity'); } catch (e) {}
		showIdentity('unlock');
		window.__DAIMOND_READY = true;
		// The app is on screen, asking for a passphrase. That is where the
		// machine's part of starting up ends and the person's begins, so it
		// is what "how long did it make me wait" means. Recorded, not sent:
		// see `openMs`.
		if (!pg.openMs) pg.openMs = Math.round(performance.now());
		return;
	}

	// A device that was REMOVED from the account, not merely locked out. The
	// identity here was taken away deliberately (`DaimondIdentity.retire()`,
	// called from `onThisDeviceRemoved`), not lost to a bad read, so it gets a
	// different screen from the orphan-evidence recover below: no "Try again"
	// that can never work, a lead that says plainly what happened, and the
	// create screen's pairing entry (always on that screen, see pairing.js
	// `injectEntryPoints`) so linking back in is one tap away. Checked BEFORE
	// the orphan-evidence branch: `purgeAll()` has already dropped what that
	// branch would otherwise find, and even if a stray ciphertext survived it,
	// "removed" is the true reason and must win.
	if (identityAvailable() && DaimondIdentity.removed()) {
		renderAll();
		if (!pg.openMs) pg.openMs = Math.round(performance.now());
		fillSettings();
		showIdentity('create');
		var removedLead = document.getElementById('id-lead');
		if (removedLead) removedLead.textContent = tOr('identity.lead_removed',
			'This device was removed from the account. Link it again with a '
			+ 'pairing code, or start a new account.');
		window.__DAIMOND_READY = true;
		return;
	}

	// The keys did not read even after the settled retry. Before offering a bare
	// create — which would mint a fresh identity OVER any sealed data still here —
	// check whether this account has already held an identity. If it has, the read
	// is a genuine loss (or a cold read the retry could not outlast), and minting
	// would orphan the sealed keys for good. So show the locked recover screen and
	// leave the create for an explicit, acknowledged choice; only a truly first
	// run (no evidence) reaches the bare create below.
	if (identityAvailable() && orphanIdentityEvidence()) {
		pg.locked = true;
		document.body.classList.add('locked');
		sessionNameEl.textContent = '';
		chatInputBar.style.display = 'none';
		try { DaimondTrail.note('lock screen', 'boot found orphan evidence, keys unread'); } catch (e) {}
		showIdentity('unlock');
		showRecover();
		window.__DAIMOND_READY = true;
		if (!pg.openMs) pg.openMs = Math.round(performance.now());
		return;
	}

	renderAll();
	// The other way boot ends: no stored identity, so the app itself is drawn.
	if (!pg.openMs) pg.openMs = Math.round(performance.now());
	fillSettings();          // the pane is on screen; it shows what is configured
	if (identityAvailable() && !cfgReady(pg.cfg) && !pg.cfg.apiKey) {
		showIdentity('create');
	} else if (!cfgReady(pg.cfg)) {
		openSettings('');
	}
}

/// Returning from Stripe. The webhook credits the ledger, and it can land a
/// moment after the browser gets redirected back, so a single read would
/// often show the old balance and look like the payment had failed.
async function handleCheckoutReturn() {
	if (!window.DaimondGateway) return;
	var buy = DaimondGateway.consumeReturn();
	if (!buy) return;
	// Checkout finished and Stripe sent them back. The gap between this and
	// `buy.open` is where money is lost, and a cancel is on the other side of
	// that gap -- so only a completed purchase is reported, and which one.
	if (buy === 'credits' || buy === 'pro') tel('buy.done', telOrd('OFFERS', buy));
	if (buy === 'cancel' || buy === 'card:cancel') {
		noticeDialog(t('checkout.cancelled'), t('checkout.cancelled_body'));
		return;
	}
	// A card came back from Stripe. Nothing was charged, so there is no balance to wait on --
	// but the card arrives by WEBHOOK, so the panel is drawn after a moment's grace rather
	// than immediately, when the gateway would still say there is no card.
	if (buy === 'card:saved') {
		openCredits('');
		for (var k = 0; k < 8; k++) {
			await new Promise(function (r) { setTimeout(r, 800); });
			if (window.DaimondAutoReload) await DaimondAutoReload.render();
			var st = window.DaimondAutoReload && DaimondAutoReload.settings();
			if (st && st.card && st.card.saved) {
				noticeDialog(t('checkout.card_saved'), t('checkout.card_saved_body'));
				return;
			}
		}
		noticeDialog(t('checkout.card_saved'), t('checkout.card_pending_body'));
		return;
	}
	// Pro came back from Stripe. The licence is minted by WEBHOOK, so it may
	// lag the redirect by a moment; poll the licence rather than read it once.
	if (buy === 'pro') {
		openCredits('');
		for (var pk = 0; pk < 12; pk++) {
			await new Promise(function (r) { setTimeout(r, 900); });
			var held = await DaimondGateway.refreshLicence();
			renderCredits();
			if (held) {
				if (window.DaimondSync && DaimondSync.recheck) DaimondSync.recheck();  // sync is on now
				noticeDialog(t('checkout.pro_unlocked'), t('checkout.pro_unlocked_body'));
				return;
			}
		}
		noticeDialog(t('checkout.received'), t('checkout.pro_pending_body'));
		return;
	}
	var before = DaimondGateway.state().credits;
	for (var i = 0; i < 10; i++) {
		await new Promise(function (r) { setTimeout(r, 1000); });
		await DaimondGateway.refreshBalance();
		var now = DaimondGateway.state().credits;
		if (now !== null && now !== before) {
			renderCredits(); updateSpend();
			// The balance moved, so the key minted against the old one is worth less than the
			// account now is -- and a user who has just topped up from nothing has no key at
			// all. Mint against what they actually have before telling them it is theirs.
			await syncCredits();
			noticeDialog(t('credits.added'),
				DaimondI18n.fillPrices(document.createElement('span'), t('credits.now',
					{ amount: DaimondI18n.priceMarkMinor(now, DaimondGateway.state().currency) })));
			return;
		}
	}
	renderCredits(); updateSpend();
	syncCredits();
	noticeDialog(t('checkout.received'), t('checkout.credits_pending_body'));
}
