// ── TRAINING WHEELS — remove after beta. ─────────────────────
//
// The EVENT seam. One guarded call, so a call site is one line and the whole
// feed lifts out in one grep of `DEBUG_SHARE`. `DEBUG_SHARE.event` is itself a
// no-op when sharing is off and never throws into its caller, so this guard is
// belt-and-braces against the module being absent altogether (a build with the
// script tag removed) rather than against the feed misbehaving.
/// A chat's turn replaced or removed files, and the chat's own store kept a copy
/// of each (`record_chat_turn`, src/wasm/app.rs): offer them back.
///
/// A chat has no History panel of its own, so this toast is the page's door, and
/// `file_revert` -- offered to a chat since the store existed -- is the one the
/// user reaches by asking.
///
/// ONLY WHILE THE CHAT IS ON SCREEN (r547 QA-B F3). A turn that ended while another
/// chat was showing raised the toast over that chat, and Undo there reverted the first
/// chat's files. So `shown` (the turn's own `owns`) gates the offer, and the window is
/// withdrawn the moment the chat leaves the screen (`DaimondUndo.check`).
export function offerTurnUndo(ev, shown) {
	var files = Array.isArray(ev.files) ? ev.files.slice() : [];
	if (!files.length || !window.DaimondUndo || !window.DaimondVersions) return;
	var keeper = String(ev.keeper || ''), v = Number(ev.version);
	if (!keeper || !(v > 0) || typeof shown !== 'function' || !shown()) return;
	DaimondUndo.able({
		shown:  shown,
		text:   tOr('versions.turn_kept', 'Copies kept of the files this turn changed: {n}',
			{ n: files.length }),
		ms:     15000,
		revert: function () { DaimondVersions.undoVersion(keeper, v, files); },
	});
}

/// The debug feed's `tool` row, for a chat's turn and a daimon's alike.
///
/// The tool's name, the SIZES of its arguments and its result, and the engine's
/// outcome word -- and, for a call that can remove or replace a file, where its
/// path sat when the call met it, as the engine measured it (`ev.class`, see
/// `PathClass` in src/tools.rs): `pd` its depth, `pk` file, folder or none, `po`
/// inside a folder open on this computer, `px` refused. Never a path, never an
/// argument, never the result: a tool result is a file read or a command's output.
///
/// A call the engine did not complete is the exception (D-20261008-02, owner's ruling):
/// its row also names the Diamond and the chat, and carries the engine's own refusal or
/// error sentence as `full`, which `DEBUG_SHARE` scrubs of keys, caps at 300 characters
/// and ships as a chunked set the row points at (`mref`), with its head as `msg`.
///
/// # Arguments
/// * `ev` - The engine's `tool_result` event.
/// * `args` - The call's arguments as sent, measured and never read.
/// * `ctx` - `{dia, chat}`: the Diamond and the chat the turn belongs to.
export function lensToolRow(ev, args, turn, step, ctx) {
	var row = {
		turn: String(turn || ''), r: step,
		name: String(ev.name || '').slice(0, 40),
		ab:   args ? String(args).length : 0,
		rb:   String(ev.content || '').length,
		out:  String(ev.outcome || '').slice(0, 16),
	};
	if (ev.outcome !== 'done') {
		row.dia  = String((ctx && ctx.dia) || '');
		row.chat = String((ctx && ctx.chat) || '');
		row.full = String(ev.content || '');
	}
	var c = null;
	try { c = ev.class ? JSON.parse(String(ev.class)) : null; } catch (e) { c = null; }
	if (c && typeof c === 'object') {
		row.pd = Number(c.d) | 0;
		row.pk = ['file', 'folder', 'none'].indexOf(c.k) >= 0 ? c.k : '';
		row.po = c.open ? 1 : 0;
		row.px = c.refused ? 1 : 0;
	}
	return row;
}

// One turn's `round` rows (`DEBUG_SHARE.roundFeed`), or a no-op where the feed is absent.
export function dsRounds() {
	try {
		if (window.DEBUG_SHARE && DEBUG_SHARE.roundFeed) return DEBUG_SHARE.roundFeed();
	} catch (e) { /* the feed must never break the app */ }
	return { add: function () {}, flush: function () {}, meta: function () { return { p: 0, ca: 0, o: 0 }; } };
}

// ONE `round_meta` (or `stalled`) feed row, for the chat, the worker and the daimon alike, onto
// `row`'s own keys (`turn` or `w`, `r`, `dia`). `use` is the round's `rounds.meta(ev)`.
// The round's timing facts (U3a RM): `by` body bytes, `f` ms to the first byte, `g` the
// longest quiet after it, `ms` the round's length; `lens gaps` reads them. Bytes ride as `by`,
// NOT `b`: the feed's envelope `b` is the build tag, and it overwrote them (D-20261020-10).
// Host speed (D-20261020-10): `o` output tokens, `tf` ms to the first token that grew the
// reply, `tps` tokens a second from there, beside `provider`, the host that served it.
export function roundMetaRow(row, ev, use) {
	var num = function (v) { return Math.round(Number(v) || 0); };
	var o = num(ev.o), gm = num(ev.gm);
	row.gen      = String(ev.gen || '').slice(0, 40);
	row.finish   = String(ev.finish || '').slice(0, 24);
	row.nfinish  = String(ev.nfinish || '').slice(0, 24);
	row.provider = String(ev.provider || '').slice(0, 40);
	row.p        = use.p;
	row.ca       = use.ca;
	row.by       = num(ev.b);
	row.f        = num(ev.f);
	row.g        = num(ev.g);
	row.ms       = num(ev.ms);
	row.o        = o;
	row.tf       = num(ev.tf);
	row.tps      = (gm > 0 && o > 0) ? Math.round(o * 10000 / gm) / 10 : 0;
	return row;
}
// page-split: install 129

export function install() { // page-split: install
	// page-split: install 128
	// The document used to REPLACE the chat, so closing it had to put the chat
	// back. It is a stage panel now and sits beside the chat, so its own closer
	// is the whole of it: there is nothing to restore.

	// Leaving with agents in flight kills them: their fetches die with the page.
	window.addEventListener('beforeunload', function (e) {
		if (!Workers.busy() || _enginePoison) return;		// the poison's reload is not held
		e.preventDefault();
		e.returnValue = '';
	});
	// page-split: install 129

	// The Lens's picture of this screen: a toast before every one, and a Diamond page that cannot
	// draw itself is a box labelled as one.
	if (window.DaimondLensShot) {
		DaimondLensShot.wire({
			notify:     function () { toast(t('lens.shot_toast')); },
			frameLabel: t('lens.frame_label'),
		});
	}

	// The one data seam for the temporary debug-sharing feature (the toggle is in
	// Settings; everything else is www/js/debugshare.js). This hands that module a
	// function returning THIS closure's decrypted, private-scope state -- the
	// transcripts, config, roster, presence and election it cannot otherwise see --
	// which the module redacts (keys to fingerprints) and ships only while the
	// owner has the switch on. READS existing state only; touches nothing. Lifts
	// out with the module in one grep of `DEBUG_SHARE`.
	if (window.DEBUG_SHARE && DEBUG_SHARE.registerProvider) {
		DEBUG_SHARE.registerProvider(async function () {
			var transcripts = null;
			try { transcripts = await chatsWithTranscripts(storedChats()); } catch (e) { transcripts = null; }
			var roster = null;
			try { roster = loadDevices(); } catch (e) {}
			var presence = null;
			try { presence = (window.DaimondPresence && DaimondPresence.snapshot && DaimondPresence.snapshot()) || null; } catch (e) {}
			var election = null;
			try {
				election = {
					self:      selfDeviceId(),
					nominated: nominatedDeviceId(),
					trace:     _electionTrace,
				};
			} catch (e) {}
			// The config goes whole; the module's redactor fingerprints `apiKey`,
			// `apiKeyEnc`, `pushToken` and anything else key-shaped before it ships.
			var config = null;
			try { config = JSON.parse(JSON.stringify(pg.cfg)); } catch (e) { config = null; }
			var tokenStats = null;
			try {
				tokenStats = (Array.isArray(pg.chats) ? pg.chats : []).map(function (c) {
					var win = 0;
					try {
						win = (window.DaimondPricing && DaimondPricing.contextWindow)
							? (DaimondPricing.contextWindow(turnModelOf(c).model, turnModelOf(c).provider) || 0) : 0;
					} catch (e) {}
					return {
						id:       c.id,
						name:     c.name,
						model:    turnModelOf(c).model,
						provider: turnModelOf(c).provider,
						messages: Array.isArray(c.messages) ? c.messages.length : (c.msgCount || 0),
						contextWindow: win,
					};
				});
			} catch (e) {}
			return {
				config:      config,
				transcripts: transcripts,
				roster:      roster,
				presence:    presence,
				election:    election,
				tokenStats:  tokenStats,
			};
		});
	}

	// The live-stats seam for the same debug feed. Unlike the provider above this
	// is called EVERY telemetry tick, so it must be cheap and synchronous and read
	// no transcripts -- just the live context/token/worker numbers off the active
	// chat's wasm handle. Lifts out with the module in one grep of `DEBUG_SHARE`.
	if (window.DEBUG_SHARE && DEBUG_SHARE.registerStats) {
		DEBUG_SHARE.registerStats(function () {
			var chat = pg.current || null;
			var app  = (chat && chat.app) ? chat.app : null;
			var contextActual = null, contextWindow = null, foldAt = null;
			// `live_last_prompt_tokens` is the last round's prompt count, i.e. the size
			// of the context as the engine last sent it, in TOKENS. This tick runs
			// EVERY telemetry beat, turn running or not, so it reads the live/agent-side
			// getter rather than `last_prompt_tokens`, which borrows the session
			// `run_turn` holds mutably for the whole turn and draws zero while one runs.
			try {
				if (app) {
					contextActual = app.live_last_prompt_tokens || 0;
					contextWindow = app.context_window || 0;
					foldAt        = app.fold_at || 0;
				}
			} catch (e) {}
			// TODO(debug-feed): expose context estimate — needs a wasm getter. The
			// pre-turn byte/token gauge (`gauge.tokens`) is not surfaced to JS, so the
			// estimate is left out here rather than adding a wasm getter.
			var workerState = null;
			try {
				workerState = {
					active: (Workers && Workers.active) || 0,
					queued: (Workers && Workers.queue) ? Workers.queue.length : 0,
					busy:   !!(Workers && Workers.busy && Workers.busy()),
				};
			} catch (e) {}
			return {
				contextActual: contextActual,
				contextWindow: contextWindow,
				foldAt:        foldAt,
				activeModel:   chat ? turnModelOf(chat).model : '',
				provider:      chat ? turnModelOf(chat).provider : '',
				workerState:   workerState,
				activity:      workerState ? (workerState.busy ? 'busy' : 'idle') : null,
			};
		});
	}

	// The screen seam for the same debug feed (owner, 2026-09-13): what the
	// person is actually LOOKING AT. The iPhone PWA cannot be driven from Linux,
	// so this is the one lane that carries what a screenshot would show, without
	// carrying a screenshot -- read straight off the same state the screen itself
	// is drawn from, never off a second copy of it. Cheap and synchronous, like
	// the stats seam above; the fields it cannot answer (window size, tab
	// visibility, the updater's state) are added by debugshare.js itself.
	if (window.DEBUG_SHARE && DEBUG_SHARE.registerScreen) {
		DEBUG_SHARE.registerScreen(function () {
			// Which of the app's own surfaces is up. `admin` and the quick
			// appearance popover are read straight off the elements they toggle;
			// short of those, `centreMode` is the app's own answer for the AI
			// panel's face -- 'chat', 'focus' (a Diamond's crystal) or 'daimon'
			// (a Diamond's own conversation). The guide is a SEPARATE tab
			// (`window.open`, see the button beside it) and cannot be seen from
			// here at all -- left out rather than guessed at.
			var view = 'chat';
			try {
				var adminEl = document.getElementById('admin');
				var menuEl  = document.getElementById('settings-menu');
				if (adminEl && adminEl.classList && adminEl.classList.contains('admin-open')) view = 'admin';
				else if (menuEl && !menuEl.hidden) view = 'settings';
				else if (pg.centreMode === 'focus') view = 'diamond';
				else if (pg.centreMode === 'daimon') view = 'daimon';
			} catch (e) { /* the DOM is not up yet */ }
			// The seat switch, read as rendered rather than recomputed -- what this
			// answers is what the person actually SEES by the composer, not a second
			// opinion that could drift from it: the pressed segment's words, '' when
			// the switch is not drawn.
			var seat = '';
			try {
				var sw = document.getElementById('seat-switch');
				var on = (sw && !sw.hidden) ? sw.querySelector('.dview-btn[aria-pressed="true"]:not([hidden])') : null;
				seat = on ? String(on.textContent || '') : '';
			} catch (e) { /* no seat switch mounted */ }
			// The last message of the CURRENT chat, role and text; debugshare.js
			// combines and clips them. A daimon's log roles ('fold_log', 'tool', ...)
			// travel just as honestly as 'user'/'assistant' -- whatever tile is last
			// is what is on screen.
			var role = '', text = '';
			try {
				var msgs = (pg.current && Array.isArray(pg.current.messages)) ? pg.current.messages : [];
				var last = msgs.length ? msgs[msgs.length - 1] : null;
				if (last) {
					role = String(last.role || '');
					text = logRowText(last);
				}
			} catch (e) { /* no current chat yet */ }
			// What is in front of the person, cheaply and honestly: the app's own
			// modal, a build waiting on a reload, the identity gate, and a build the
			// watch has given up advancing on its own.
			//
			// TODO(debug-feed): a consent/ask/blocker/runner-confirm TILE is real
			// screen state too, but it lives on `Pending`'s own list rather than
			// behind one flag reachable here -- left for a later pass rather than
			// guessed at. A tile is not a modal and does not stop anybody reading
			// the screen, which is why it is the lesser of the two omissions.
			var dlg = 'none';
			// THE APP'S OWN MODAL FIRST, because it is the thing actually covering the
			// screen. On 2026-09-13 the beat said `dlg none` for eleven minutes with the
			// network question up and a daimon's turn stopped behind it -- the one lane
			// carrying what a screenshot would show, saying nothing was there
			// (`dev/HATES.md`, turn 54). `.modal.dlg` is the root `dialog()` builds and
			// the selector `someoneCanAnswer` keys on, so the two cannot disagree about
			// whether a card is up; `data-kind` is stamped on it there. The heading is
			// the reader's own words and travels as it is drawn, clipped by debugshare.js.
			try {
				var card = document.querySelector('.modal.dlg');
				if (card) {
					var kind = String(card.getAttribute('data-kind') || 'dlg');
					var head = card.querySelector('h2');
					var title = head ? String(head.textContent || '').trim() : '';
					dlg = title ? (kind + ': ' + title) : kind;
				}
			} catch (e) { /* the DOM is not up yet */ }
			// A card on screen outranks a pending build: the updater's state is reported
			// in its own `upd` field either way, so nothing is lost by yielding here.
			try {
				var U = dlg === 'none' ? window.DaimondUpdater : null;
				if (U && U.pending && U.pending()) {
					var left = U.countdown ? U.countdown() : 0;
					if (left > 0) dlg = 'update-countdown: reload in ' + left + 's';
					else if (U.stuck && U.stuck()) dlg = 'stale-build: reload needed';
					else if (U.gaveUp && U.gaveUp()) dlg = 'stale-build: waiting for a safe moment';
				}
				if (dlg === 'none' && pg.locked) dlg = 'lock: unlock';
			} catch (e) { /* the updater has not polled yet */ }
			return {
				view:   view,
				seat:   seat,
				role:   role,
				text:   text,
				dlg:    dlg,
				comp:   (chatInput && chatInput.value) ? chatInput.value.length : 0,
				locked: !!pg.locked,
			};
		});
	}

	// A throw in boot before its own try (where markFailed is called) would leave
	// DaimondSeal.ready pending for good and every waiting send hung; settle it here.
	boot().then(handleCheckoutReturn, function (e) {
		try { window.DaimondSeal.markFailed(e); } catch (e2) { /* no seal bridge */ }
		throw e;
	});
} // page-split: end install
